import datetime
HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MO = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
ONE = datetime.timedelta(days=1)
def bd(d, HOL=HOL):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nextbd(d, bd=bd, ONE=ONE):
    d = d + ONE
    while not bd(d):
        d = d + ONE
    return d
def sp(d, WD=WD, MO=MO):
    return '%s %d %s %d' % (WD[d.weekday()], d.day, MO[d.month - 1], d.year)
def money(x):
    try:
        x = float(x)
        if abs(x - round(x)) < 0.005:
            return '%d' % int(round(x))
        return '%.2f' % x
    except Exception:
        return str(x)

vars['cb_allowed'] = 'not known'
vars['line_status'] = ''
vars['id_move'] = 'other'
vars['tp_move'] = 'other'
vars['move'] = 'other'
vars['named_amount'] = 0
vars['amount_fact'] = 'none yet'
vars['offer_fact'] = 'none yet'
try:
    now = datetime.datetime.fromisoformat(str(vars.get('now') or '')[:16])
    today = now.date()
    lines = []
    hhmm = now.strftime('%H:%M')
    if hhmm < '19:00':
        if hhmm < '10:00':
            lines.append('- TODAY, %s (%s): allowed from %s to %s, both included.' % (sp(today), today.isoformat(), '10:00', '19:00'))
        else:
            lines.append('- TODAY, %s (%s): allowed only LATER than %s (the time now) and up to %s included.' % (sp(today), today.isoformat(), hhmm, '19:00'))
    else:
        lines.append('- TODAY, %s (%s): NOT allowed any more, it is already %s.' % (sp(today), today.isoformat(), hhmm))
    nb = nextbd(today)
    d = today + ONE
    k = 0
    while k < 9:
        if d == nb:
            lines.append('- %s (%s)%s: allowed from %s to %s, both included. This is the next business day.' % (sp(d), d.isoformat(), ' = tomorrow' if k == 0 else '', '10:00', '19:00'))
        else:
            lines.append('- %s (%s)%s: NOT allowed at any time.' % (sp(d), d.isoformat(), ' = tomorrow' if k == 0 else ''))
        d = d + ONE
        k = k + 1
    lines.append('- Any other day: NOT allowed. Any time before %s or after %s: NOT allowed.' % ('10:00', '19:00'))
    vars['cb_allowed'] = chr(10).join(lines)
except Exception:
    pass

