        vars['persuasion_used'] = used
        if used == 1:
            state = 'attempt1'
            amt = vars.get('floor_text') if floor_named else vars.get('past_due_text')
            vars['a1_amount_text'] = str(amt)
            vars['offer_fact'] = 'amount %s on %s = %s' % (amt, vars.get('a1_date_spoken'), vars.get('a1_date_iso'))
